import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const AMOUNT_PATTERN = /^\d+(\.\d+)?$/;

function dateOf(value: unknown): string {
  if (typeof value !== 'string' || !DATE_PATTERN.test(value)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '날짜는 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  return value;
}

function idOf(value: unknown, label: string): string {
  const text = String(value ?? '');
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 선택해 주세요.');
  }
  return text;
}

function amountOf(value: unknown, label: string, required: boolean): string | null {
  if (value === undefined || value === null || value === '') {
    if (required) {
      throw new ApiError(400, 'VALIDATION_FAILED', label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  const text = typeof value === 'number' && Number.isFinite(value) ? String(value) : typeof value === 'string' ? value.trim() : '';
  if (!AMOUNT_PATTERN.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '은(는) 0 이상의 숫자로 입력해 주세요.');
  }
  return text;
}

@Controller('api/v1')
export class FnSfr00305Controller {
  @Post('/cashier-closing-periods')
  @HttpCode(200)
  async createCashierClosingPeriod(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const startDate = dateOf(data['startDate']);
    const endDate = dateOf(data['endDate']);
    return transaction(async (db) => {
      const checkRows = await db.query(
        `SELECT CAST(:endDate AS date) < CAST(:startDate AS date) AS "invalid"`,
        { startDate, endDate },
      );
      if (checkRows[0]['invalid'] === true) {
        throw new ApiError(422, 'INVALID_CLOSING_PERIOD', '폐쇄 종료일은 시작일보다 빠를 수 없습니다.');
      }
      const rows = await db.query(
        `INSERT INTO cashier_closing_period (start_date, end_date, created_at, updated_at)
         VALUES (CAST(:startDate AS date), CAST(:endDate AS date), now(), now())
         RETURNING cashier_closing_period_id AS "cashierClosingPeriodId",
                   to_char(start_date, 'YYYY-MM-DD') AS "startDate",
                   to_char(end_date, 'YYYY-MM-DD') AS "endDate"`,
        { startDate, endDate },
      );
      return rows[0];
    });
  }

  @Post('/budget-carryovers')
  @HttpCode(200)
  async createBudgetCarryover(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const projectId = idOf(data['projectId'], '프로젝트');
    const budgetItemId = idOf(data['budgetItemId'], '예산과목');
    const carryoverAmount = amountOf(data['carryoverAmount'], '이월 대상 금액', true);
    const initialCarryoverAmount = amountOf(data['initialCarryoverAmount'], '초기 이월 금액', false);
    return transaction(async (db) => {
      const projects = await db.query(
        `SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)`,
        { projectId },
      );
      const items = await db.query(
        `SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:budgetItemId AS bigint)`,
        { budgetItemId },
      );
      if (projects.length === 0 || items.length === 0) {
        throw new ApiError(404, 'PROJECT_OR_BUDGET_ITEM_NOT_FOUND', '프로젝트 또는 예산과목을 찾을 수 없습니다.');
      }
      const dup = await db.query(
        `SELECT budget_carryover_id FROM budget_carryover
         WHERE project_id = CAST(:projectId AS bigint) AND budget_item_id = CAST(:budgetItemId AS bigint)`,
        { projectId, budgetItemId },
      );
      if (dup.length > 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '이미 이월이 등록된 프로젝트·예산과목입니다.');
      }
      const rows = await db.query(
        `INSERT INTO budget_carryover (project_id, budget_item_id, carryover_amount, initial_carryover_amount, created_at, updated_at)
         VALUES (CAST(:projectId AS bigint), CAST(:budgetItemId AS bigint), CAST(:carryoverAmount AS numeric), CAST(:initialCarryoverAmount AS numeric), now(), now())
         RETURNING budget_carryover_id AS "budgetCarryoverId",
                   project_id AS "projectId",
                   budget_item_id AS "budgetItemId",
                   carryover_amount AS "carryoverAmount",
                   initial_carryover_amount AS "initialCarryoverAmount"`,
        { projectId, budgetItemId, carryoverAmount, initialCarryoverAmount },
      );
      return rows[0];
    });
  }
}

