import { useState } from 'react';
import {
  call,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  RefName,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr00305Page({ role, notify }: PageProps) {
  const [periods, setPeriods] = useState<Row[]>([]);
  const [carryovers, setCarryovers] = useState<Row[]>([]);
  const [drawer, setDrawer] = useState<'' | 'period' | 'carryover'>('');

  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const [projectId, setProjectId] = useState<number | string>('');
  const [budgetItemId, setBudgetItemId] = useState<number | string>('');
  const [carryoverAmount, setCarryoverAmount] = useState<number | string>('');
  const [initialCarryoverAmount, setInitialCarryoverAmount] = useState<number | string>('');

  function closeDrawer() {
    setDrawer('');
  }

  async function submitPeriod() {
    if (!startDate || !endDate) {
      throw new Error('폐쇄 시작일과 종료일을 입력해 주세요.');
    }
    if (endDate < startDate) {
      throw new Error('폐쇄 종료일은 시작일보다 빠를 수 없습니다.');
    }
    const result = await call('POST', '/cashier-closing-periods', role, { startDate, endDate });
    setPeriods([result, ...periods]);
    setStartDate('');
    setEndDate('');
    closeDrawer();
    notify('폐쇄기간을 설정했습니다.');
  }

  async function submitCarryover() {
    if (projectId === '' || budgetItemId === '') {
      throw new Error('프로젝트와 예산과목을 선택해 주세요.');
    }
    if (carryoverAmount === '') {
      throw new Error('이월 대상 금액을 입력해 주세요.');
    }
    const body: Row = { projectId, budgetItemId, carryoverAmount };
    if (initialCarryoverAmount !== '') {
      body.initialCarryoverAmount = initialCarryoverAmount;
    }
    const result = await call('POST', '/budget-carryovers', role, body);
    setCarryovers([result, ...carryovers]);
    setProjectId('');
    setBudgetItemId('');
    setCarryoverAmount('');
    setInitialCarryoverAmount('');
    closeDrawer();
    notify('예산 이월을 등록했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['설정한 폐쇄기간', periods.length],
            ['등록한 이월', carryovers.length],
          ]}
        />
      </section>

      <section className="box span-6">
        <h2>폐쇄기간</h2>
        <Band total={periods.length}>
          <button type="button" onClick={() => setDrawer('period')}>
            폐쇄기간 설정
          </button>
        </Band>
        <DataTable
          rows={periods}
          empty="이 화면에서 설정한 폐쇄기간이 없습니다."
          columns={[
            { key: 'cashierClosingPeriodId', label: '출납 폐쇄기간 ID' },
            { key: 'startDate', label: '폐쇄 시작일', render: (row) => <DateText value={row.startDate} /> },
            { key: 'endDate', label: '폐쇄 종료일', render: (row) => <DateText value={row.endDate} /> },
          ]}
        />
      </section>

      <section className="box span-6">
        <h2>예산 이월</h2>
        <Band total={carryovers.length}>
          <button type="button" onClick={() => setDrawer('carryover')}>
            이월 등록
          </button>
        </Band>
        <DataTable
          rows={carryovers}
          empty="이 화면에서 등록한 이월이 없습니다."
          columns={[
            { key: 'projectId', label: '프로젝트', render: (row) => <RefName table="project" role={role} value={row.projectId} /> },
            { key: 'budgetItemId', label: '예산과목', render: (row) => <RefName table="budget_item" role={role} value={row.budgetItemId} /> },
            { key: 'carryoverAmount', label: '이월 대상 금액', render: (row) => <Num value={row.carryoverAmount} /> },
            { key: 'initialCarryoverAmount', label: '초기 이월 금액', render: (row) => <Num value={row.initialCarryoverAmount} /> },
          ]}
        />
      </section>

      {drawer === 'period' && (
        <Drawer title="폐쇄기간 설정" onClose={closeDrawer}>
          <Form onSubmit={submitPeriod} submit="설정">
            <Field label="폐쇄 시작일" required>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="폐쇄 종료일" required>
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
          </Form>
        </Drawer>
      )}

      {drawer === 'carryover' && (
        <Drawer title="예산 이월 등록" onClose={closeDrawer}>
          <Form onSubmit={submitCarryover} submit="등록">
            <Field label="프로젝트" required>
              <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} />
            </Field>
            <Field label="예산과목" required>
              <LookupSelect table="budget_item" role={role} value={budgetItemId} onChange={setBudgetItemId} />
            </Field>
            <Field label="이월 대상 금액" required>
              <NumberInput value={carryoverAmount} onChange={setCarryoverAmount} />
            </Field>
            <Field label="초기 이월 금액">
              <NumberInput value={initialCarryoverAmount} onChange={setInitialCarryoverAmount} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
